/* ------------------------------------------------------------------ hero compositions (21st.dev-inspired) */
const H2 = {
  fan: ['atelier', 'loom', 'vellum', 'solstice', 'garden', 'hum', 'coral', 'specimen', 'dose'],
  ring: ['sticker', 'squeeze', 'terrazzo', 'bloom', 'ink'],
  overlay: ['editorial', 'formwork', 'darkroom', 'kiln', 'spore', 'dusk', 'manifesto', 'broadside', 'rim', 'hedgerow'],
  mock: ['cobalt', 'midnight', 'console', 'vantage', 'terminal', 'ultraviolet', 'blueprint', 'almanac', 'wayfind', 'furrow'],
  accordion: ['werkstatt', 'carnival', 'brutal', 'piste', 'sport', 'arcade', 'halftone', 'overprint', 'pasteup'],
  centered: ['lumen', 'refract', 'ribbon', 'grid', 'newsprint', 'studio', 'riso', 'midnight']
};
function heroKind(d) { for (const k of Object.keys(H2)) if (H2[k].includes(d.id)) return k; return 'split'; }
const pill = d => `<span class="bar" style="display:inline-flex;gap:8px;padding:5px 6px 5px 14px;border-radius:999px;background:var(--s);border:1px solid var(--ln);font-size:14px;font-weight:600;color:var(--ci)"><span class="tag" style="background:var(--a);color:var(--ai)">${L('New', 'ใหม่')}</span>${L('Spring campaign kit is out', 'ชุดแคมเปญฤดูใบไม้ผลิมาแล้ว')} ${ic('arrow', 15)}</span>`;
const proof = d => `<div class="bar" style="gap:12px;justify-content:inherit"><span class="bar" style="gap:0">${['N', 'S', 'K', 'A'].map((x, i) => `<span class="av" style="width:34px;height:34px;margin-left:${i ? -10 : 0}px;border:2px solid var(--g);background:var(--t${i % 4})">${x}</span>`).join('')}</span><span>${stars(5, 15)}</span><span class="sm">${L('Loved by 120+ teams (sample)', 'ทีมกว่า 120 แห่งไว้วางใจ (ตัวอย่าง)')}</span></div>`;
const logoCloud = d => `<div class="wrap" style="padding:34px 40px"><div class="bar" style="justify-content:space-between;opacity:.65">${['Northwind', 'Baan Lanna', 'Mango', 'Siam Fresh', 'Chao Phraya', 'Studio'].map(x => `<span style="font:${d.dw} 22px/1 '${d.display}',sans-serif;text-transform:${d.case};letter-spacing:${d.track}">${x}</span>`).join('')}</div><p class="sm" style="text-align:center;margin-top:10px">${L('Placeholder names. Real logos only with written permission.', 'ชื่อสมมติ โลโก้จริงเมื่อได้รับอนุญาตเท่านั้น')}</p></div>`;
const heroText = (d, size, align) => `<div style="text-align:${align};display:flex;flex-direction:column;gap:20px;align-items:${align === 'center' ? 'center' : 'flex-start'}">${pill(d)}<h1 style="font-size:${size}px;max-width:${align === 'center' ? 1000 : 720}px">${L('Brands people remember, not just notice.', 'แบรนด์ที่คนจำได้ ไม่ใช่แค่คนเห็น')}</h1><p class="lead" style="max-width:600px">${L('Strategy, design, content and paid media in one team.', 'กลยุทธ์ ออกแบบ คอนเทนต์ และโฆษณา ในทีมเดียว')}</p><div class="row"><a class="btn">${L('Book a 30-min call', 'นัดคุย 30 นาที')}</a><a class="btn o">${L('See the work', 'ดูผลงาน')}</a></div>${proof(d)}</div>`;
const mockWin = d => `<div class="card" style="max-width:1020px;margin:0 auto;border-radius:${Math.max(d.radius, 14)}px;overflow:hidden;box-shadow:0 40px 80px -30px rgba(0,0,0,.45);-webkit-mask-image:linear-gradient(#000 72%,transparent);mask-image:linear-gradient(#000 72%,transparent)"><div class="bar" style="padding:12px 16px;border-bottom:1px solid var(--ln)"><i style="width:11px;height:11px;border-radius:50%;background:var(--ln)"></i><i style="width:11px;height:11px;border-radius:50%;background:var(--ln)"></i><i style="width:11px;height:11px;border-radius:50%;background:var(--ln)"></i><span class="sm" style="margin:0 auto">plume.example/campaign</span></div><div style="display:grid;grid-template-columns:170px 1fr;min-height:330px"><div style="border-right:1px solid var(--ln);padding:16px;display:flex;flex-direction:column;gap:10px">${[L('Overview', 'ภาพรวม'), L('Campaigns', 'แคมเปญ'), L('Content', 'คอนเทนต์'), L('Reports', 'รายงาน')].map((x, i) => `<div style="padding:8px 10px;border-radius:${Math.min(d.radius, 10)}px;${i === 0 ? 'background:var(--t0);font-weight:700' : 'color:var(--m)'}">${x}</div>`).join('')}</div><div style="padding:20px;display:flex;flex-direction:column;gap:16px"><div class="grid g3" style="gap:12px">${[['2.4×', L('sign-ups', 'ยอดสมัคร')], ['฿1.28M', L('paid today', 'จ่ายวันนี้')], ['-42%', L('cost per lead', 'ต้นทุนต่อลีด')]].map(k => `<div class="card pad" style="padding:14px;background:var(--t0)"><div class="sm">${k[1]}</div><div class="price" style="font-size:26px">${k[0]}</div></div>`).join('')}</div><svg viewBox="0 0 600 160" style="width:100%;height:150px"><defs><linearGradient id="gm" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="${d.accent}" stop-opacity=".35"/><stop offset="1" stop-color="${d.accent}" stop-opacity="0"/></linearGradient></defs><polygon points="0,160 0,110 60,95 120,105 180,70 240,80 300,50 360,62 420,30 480,42 540,18 600,24 600,160" fill="url(#gm)"/><polyline points="0,110 60,95 120,105 180,70 240,80 300,50 360,62 420,30 480,42 540,18 600,24" fill="none" stroke="${d.accent}" stroke-width="3" stroke-linejoin="round"/></svg></div></div></div>`;
function heroH(d) {
  const k = heroKind(d);
  if (k === 'fan') return `<section class="wrap" style="padding:56px 40px 30px;text-align:center">${heroText(d, 76, 'center')}<div style="position:relative;height:330px;margin-top:46px">${[-14, -7, 0, 7, 14].map((r, i) => `<div class="art" style="position:absolute;left:calc(50% + ${(i - 2) * 190}px - 115px);top:${Math.abs(i - 2) * 20}px;width:230px;height:290px;transform:rotate(${r}deg);box-shadow:0 22px 44px rgba(0,0,0,.22);z-index:${5 - Math.abs(i - 2)}">${art(d, ARTS2[i + 1])}</div>`).join('')}</div></section>`;
  if (k === 'ring') return `<section class="wrap" style="padding:30px 40px;position:relative;height:760px;text-align:center"><div style="position:absolute;inset:0">${Array.from({ length: 14 }, (_, i) => { const a = (i / 14) * Math.PI * 2; const x = 50 + Math.cos(a) * 44, y = 50 + Math.sin(a) * 42; const z = 70 + (i % 3) * 24; return `<div class="art" style="position:absolute;left:calc(${x}% - ${z / 2}px);top:calc(${y}% - ${z / 2}px);width:${z}px;height:${z}px;border-radius:50%;box-shadow:0 10px 24px rgba(0,0,0,.18)">${art(d, ARTS2[i % 10])}</div>`; }).join('')}</div><div style="position:relative;display:flex;justify-content:center;padding-top:150px">${heroText(d, 64, 'center')}</div></section>`;
  if (k === 'accordion') return `<section class="wrap grid" style="grid-template-columns:480px 1fr;gap:40px;align-items:center;padding:56px 40px;min-height:640px">${heroText(d, 60, 'left')}<div class="bar" style="height:520px;gap:10px;align-items:stretch">${[5, 1, 1, 1, 1].map((f, i) => `<div class="art" style="flex:${f};height:100%;border-radius:${Math.max(d.radius, 16)}px">${art(d, ARTS2[i + 2])}<span style="position:absolute;left:16px;bottom:16px;${f === 1 ? 'writing-mode:vertical-rl;transform:rotate(180deg);left:50%;margin-left:-8px;bottom:20px' : ''}" class="tag">${[L('Brand', 'แบรนด์'), L('Content', 'คอนเทนต์'), L('Media', 'โฆษณา'), L('Web', 'เว็บ'), L('Print', 'พิมพ์')][i]}</span></div>`).join('')}</div></section>`;
  if (k === 'overlay') return `<section style="position:relative;height:720px;overflow:hidden"><div class="art" style="position:absolute;inset:0;border-radius:0">${art(d, 'mesh')}</div><div style="position:absolute;inset:0;background:linear-gradient(transparent 35%,rgba(0,0,0,.55))"></div><div class="wrap" style="position:relative;height:100%;display:flex;flex-direction:column;justify-content:flex-end;padding-bottom:56px;color:#fff"><h1 style="font-size:132px;color:#fff;max-width:1100px;line-height:.92">${L('Brands people remember.', 'แบรนด์ที่คนจำได้')}</h1><div class="bar" style="margin-top:26px;justify-content:space-between"><p style="color:#fff;opacity:.9;max-width:520px;font-size:20px">${L('Strategy, design, content and paid media in one team.', 'กลยุทธ์ ออกแบบ คอนเทนต์ โฆษณา ในทีมเดียว')}</p><div class="row"><a class="btn">${L('Book a call', 'นัดคุย')}</a><a class="btn o">${L('See the work', 'ดูผลงาน')}</a></div></div></div></section>`;
  if (k === 'mock') return `<section style="position:relative;overflow:hidden"><div class="art" style="position:absolute;inset:0 0 40% 0;border-radius:0;opacity:.7">${art(d, 'mesh')}</div><div class="wrap" style="position:relative;padding:60px 40px 0;text-align:center">${heroText(d, 72, 'center')}<div style="margin-top:50px">${mockWin(d)}</div></div></section>`;
  if (k === 'centered') return `<section style="position:relative;overflow:hidden"><div class="art" style="position:absolute;inset:0;border-radius:0;opacity:.55">${art(d, 'mesh')}</div><div class="wrap" style="position:relative;padding:90px 40px 70px">${heroText(d, 84, 'center')}</div></section>`;
  return `<section class="hero-in wrap split"><div><span class="sample">${L('Sample site', 'เว็บตัวอย่าง')}</span><h1 style="margin:18px 0 20px">${L('Brands people remember, not just notice.', 'แบรนด์ที่คนจำได้ ไม่ใช่แค่คนเห็น')}</h1><p class="lead">${L('Strategy, design, content and paid media in one team.', 'กลยุทธ์ ออกแบบ คอนเทนต์ และโฆษณา ในทีมเดียว')}</p><div class="row" style="margin-top:28px"><a class="btn">${L('Book a 30-min call', 'นัดคุย 30 นาที')}</a><a class="btn o">${L('See the work', 'ดูผลงาน')}</a></div><div style="margin-top:26px">${proof(d)}</div></div>${ph(d, d.art, 440)}</section>`;
}
PAGES.hero = d => page(d, `${nav(d)}${heroH(d)}${logoCloud(d)}`);

/* ------------------------------------------------------------------ render */
const os = require('os');
(async () => {
  const mod = findModule(process.cwd());
  const exe = mod ? findBrowser(mod.chromium) : undefined;
  if (!mod || exe === undefined) { console.log('NOT RUN: no Playwright module or browser (npm i -D playwright && npx playwright install chromium)'); process.exit(3); }
  fs.mkdirSync(out, { recursive: true });
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'site-'));
  const browser = await mod.chromium.launch(exe ? { executablePath: exe } : {});
  const pg = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const fpath = (l, p) => path.join(((singles.includes(l.id) || ['sections', 'components'].includes(p)) ? out : tmp), `${l.id}-${p}${thai ? '-th' : ''}.jpg`);
  for (const p of pages) for (const l of looks) {
    const mobile = MOB.includes(p);
    await pg.setViewportSize({ width: mobile ? 390 : 1440, height: mobile ? 844 : 900 });
    await pg.setContent(PAGES[p](l), { waitUntil: 'load', timeout: 30000 }).catch(() => {});
    await pg.evaluate(() => document.fonts && document.fonts.ready).catch(() => {});
    await pg.waitForTimeout(200);
    if (mobile) await pg.screenshot({ path: fpath(l, p), type: 'jpeg', quality: 76, clip: { x: 0, y: 0, width: 390, height: 844 } });
    else if (p === 'hero') await pg.screenshot({ path: fpath(l, p), type: 'jpeg', quality: 74, clip: { x: 0, y: 0, width: 1440, height: 900 } });
    else await pg.screenshot({ path: fpath(l, p), type: 'jpeg', quality: 70, fullPage: true });
  }
  console.log(`rendered ${pages.length} pages x ${looks.length} looks`);
  if (has('--sheet')) {
    for (const p of pages.filter(x => !['sections', 'components', 'hero'].includes(x))) {
      const mobile = MOB.includes(p), tw = mobile ? 250 : 460, th = mobile ? 541 : 640, cols = mobile ? 6 : 3;
      const cells = looks.map(l => `<figure style="margin:0"><div style="width:${tw}px;height:${th}px;overflow:hidden;border:1px solid #ccc"><img src="data:image/jpeg;base64,${fs.readFileSync(fpath(l, p)).toString('base64')}" style="display:block;width:${tw}px;height:auto"></div><figcaption style="font:600 15px system-ui;padding:5px 2px">${l.name}</figcaption></figure>`).join('');
      await pg.setViewportSize({ width: cols * (tw + 24) + 24, height: 400 });
      await pg.setContent(`<body style="margin:0;padding:24px;background:#fff"><div style="display:grid;grid-template-columns:repeat(${cols},${tw}px);gap:18px 24px">${cells}</div></body>`, { waitUntil: 'load' });
      await pg.waitForTimeout(200);
      await pg.screenshot({ path: path.join(out, `sheet-${p}${thai ? '-th' : ''}.jpg`), type: 'jpeg', quality: 62, fullPage: true });
    }
    if (pages.includes('hero')) {
      const groups = [...new Set(looks.map(l => l.group))];
      for (const g of groups) {
        const items = looks.filter(l => l.group === g), tw = 480, th = 300, cols = 4;
        const cells = items.map(l => `<figure style="margin:0"><img src="data:image/jpeg;base64,${fs.readFileSync(fpath(l, 'hero')).toString('base64')}" style="display:block;width:${tw}px;height:${th}px;border:1px solid #ccc"><figcaption style="font:600 15px system-ui;padding:5px 2px">${l.name} <span style="font-weight:400;color:#666">${heroKind(l)}</span></figcaption></figure>`).join('');
        await pg.setViewportSize({ width: cols * (tw + 24) + 24, height: 400 });
        await pg.setContent(`<body style="margin:0;padding:24px;background:#fff"><div style="display:grid;grid-template-columns:repeat(${cols},${tw}px);gap:18px 24px">${cells}</div></body>`, { waitUntil: 'load' });
        await pg.waitForTimeout(200);
        await pg.screenshot({ path: path.join(out, `sheet-hero-${g}${thai ? '-th' : ''}.jpg`), type: 'jpeg', quality: 66, fullPage: true });
      }
    }
    console.log('sheets written');
  }
  await browser.close();
  fs.rmSync(tmp, { recursive: true, force: true });
})();
